SELECT FirstName
FROM teachers
WHERE Grade = 1;

SELECT COUNT(*) AS total_purchases
FROM purchase
WHERE Level = 6;

SELECT COUNT(*) AS total
FROM exhibition
WHERE (Attendance > 100 OR Ticket_Price < 10);

SELECT storm.Name
FROM storm
WHERE storm.Region_id IS NULL;

SELECT v.Song
FROM volume v
WHERE v.Weeks_on_Top > 1;

SELECT Customers.customer_name
FROM Customers
WHERE Customers.customer_payment_method_code = 'Credit Card' AND Customers.customer_orders > 2;

SELECT player.Occasion, COUNT(player.Occasion) AS number_of_players
FROM player
GROUP BY player.Occasion;

SELECT Flag
FROM captain
WHERE Ship_ID = (SELECT Ship_ID FROM Ship ORDER BY Flag DESC LIMIT 1);

SELECT COUNT(*) AS users_logged_in
FROM Users
WHERE user_login = 'logged_in';

SELECT people.Hometown
FROM people
WHERE Age > 23 AND Age < 20;

SELECT Name
FROM Manufacturers
WHERE Revenue BETWEEN 100 AND 150;

SELECT stadium.name
FROM stadium
WHERE stadium.Opening_year = (SELECT MAX(stadium.Opening_year) FROM stadium);

SELECT employees.city, COUNT(employees.id) AS count
FROM employees
GROUP BY employees.city;

SELECT Customers.customer_status_code, Customers.email_address, Customers.phone_number
FROM Customers
WHERE Customers.last_name = 'Kohler' OR Customers.first_name = 'Marina';

SELECT district.District_name
FROM district
WHERE district.City_Area > 10 OR district.City_Population > 100000;

SELECT COUNT(DISTINCT E.Essn) AS female_dependents
FROM dependent E
WHERE E.Sex = 'F';

SELECT Catalogs.catalog_publisher
FROM Catalogs
WHERE Catalogs.catalog_publisher LIKE '%Murray%';

SELECT COUNT(*) 
FROM phone
WHERE WiFi = 'No';

SELECT product_name
FROM Products
ORDER BY product_name ASC;

SELECT LName, Fname
FROM Student
WHERE Sex = 'F' AND ClubID = (SELECT ClubID FROM Club WHERE ClubName = 'Bootup Baltimore');

SELECT COUNT(*) 
FROM head
WHERE age > 56;

SELECT name
FROM technician
WHERE Team != 'NYY';

SELECT name
FROM Reviewer
WHERE stars > 3;

SELECT Character, age
FROM actor
ORDER BY age DESC;

SELECT wine.Name
FROM wine
WHERE wine.Year < 2000 OR wine.Year > 2010;

SELECT AVG(university.Enrollment)
FROM university
WHERE Founded < 1850;

SELECT Team.Name
FROM match_season
WHERE Season IS NULL OR Draft_Pick_Number IS NULL OR Draft_Class IS NULL OR Team IS NULL;

SELECT StuID
FROM Student
WHERE city_code = 'CHI';

SELECT i.name
FROM instructor i
WHERE i.salary > (SELECT salary FROM instructor WHERE i.dept_name = 'Biology');

SELECT County_ID, Population, Case_burden
FROM county_public_safety
ORDER BY Population DESC;

SELECT AVG(artist.Age), MIN(artist.Age)
FROM artist
WHERE Country = 'United States';

SELECT COUNT(*) AS count
FROM Products
WHERE product_name = 'laurel';

SELECT COUNT(*) 
FROM browser
WHERE market_share >= 5;

SELECT School_name
FROM School
ORDER BY School_name ASC;

SELECT AVG(Damage_millions_USD), MAX(Damage_millions_USD)
FROM storm
WHERE Max_speed > 1000;

SELECT city.City, city.GDP
FROM city
WHERE city.GDP = (
    SELECT MIN(city.GDP)
    FROM city
);

SELECT pilot.Pilot_name
FROM pilot
ORDER BY pilot.Rank ASC;

SELECT Class, AVG(age), MIN(age)
FROM captain
GROUP BY Class;

SELECT People_ID, Height, Weight
FROM people
ORDER BY Height DESC;

SELECT company.Company, company.Headquarters
FROM company
ORDER BY company.Market_Value DESC;

SELECT Name
FROM people
WHERE Hometown != 'Santo Domingo';

SELECT AVG(Num_of_Factories), MAX(Num_of_Shops)
FROM manufacturer
WHERE Open_Year < '1990';

SELECT B.date_incident_start, B.date_incident_end
FROM Behavior_Incident B
WHERE B.incident_type_code = 'NOISE';

SELECT Products.Name
FROM Products
WHERE Products.Price <= 200;

SELECT Mailshot_Customers.mailshot_customer_date, Mailshot_Customers.outcome_code, Mailshot_Customers.mailshot_id, Mailshot_Customers.product_category
FROM Mailshot_Customers
ORDER BY Mailshot_Customers.outcome_code, Mailshot_Customers.mailshot_id, Mailshot_Customers.product_category;

SELECT stadium.name
FROM stadium
WHERE stadium.Opening_year IS NULL;

SELECT Major
FROM Student
WHERE Major < 3;

SELECT Customers.email_address, Customers.date_of_birth
FROM Customers
WHERE Customers.first_name = 'Carole';

SELECT Dname
FROM department
WHERE Dlocation = 'Houston';

SELECT entrepreneur.Company, entrepreneur.Investor
FROM entrepreneur
JOIN people ON entrepreneur.People_ID = people.People_ID;

SELECT Products.product_description
FROM Products
WHERE product_name = 'Chocolate';

SELECT driver.Name
FROM driver
WHERE driver.Home_city = 'Hartford' AND driver.Age < 40;

SELECT MAX(operate_company.Group_Equity_Shareholding) AS max_group_equity_shareholding
FROM flight
JOIN operate_company ON flight.airport_id = operate_company.id;

SELECT Name
FROM mission
WHERE Ship_ID IS NULL;

SELECT u.School
FROM university u
WHERE u.Founded > 1850 OR u.Affiliation = 'Public';

SELECT name
FROM Companies
ORDER BY Market_Value_billion DESC;

SELECT Name
FROM candidate
WHERE Support_rate < Oppose_rate;

SELECT SUM(room_count) AS total_rooms
FROM Apartments
WHERE building_id = (SELECT building_id FROM Apartment_Buildings WHERE building_short_name = 'Columbus Square');

SELECT Documents.Document_Name, Documents.Document_ID
FROM Documents
WHERE Document_Type_Code = 'BK';

SELECT COUNT(*) AS num_states
FROM College
WHERE enr > (SELECT AVG(enr) FROM College);

SELECT C.CName
FROM Course C
WHERE C.Credits IN (3, 1) AND C.Hours = '4';

SELECT city.Name, county_public_safety.Name
FROM city
JOIN county_public_safety ON city.County_ID = county_public_safety.County_ID;

SELECT FirstName
FROM teachers
WHERE Classroom = 110;

SELECT exhibition.Theme, exhibition.Year
FROM exhibition
WHERE exhibition.Ticket_Price < 15;

SELECT state_province_county, COUNT(*) AS count_of_addresses
FROM Addresses
GROUP BY state_province_county;

SELECT Person.name
FROM Person
WHERE Person.friend IS NULL;

SELECT name
FROM races
WHERE year BETWEEN 2014 AND 2017;

SELECT school_details.Nickname
FROM school_details
WHERE school_details.Division != '1';

SELECT Party, First_Elected
FROM election
JOIN party ON election.District = party.Party_ID;

SELECT customer.cust_name, customer.acc_type, customer.credit_score
FROM customer
WHERE customer.no_of_loans = 0;

SELECT Student.StuID, Advisor
FROM Student
WHERE city_code = 'BAL';

SELECT name, email
FROM user_profiles
WHERE followers > 1;

SELECT F.Fname, F.Lname, F.Phone
FROM Faculty F
WHERE F.Sex = 'F';

SELECT product.product_name
FROM product
WHERE product.product_name LIKE '%Scanner%';

SELECT receipt_date
FROM Documents
WHERE document_id = 3;

SELECT Event_ID
FROM Events
WHERE Event_Details LIKE '%Kenyatta Kuhn%';

SELECT Fname, Lname
FROM employee
WHERE Salary > 30000;

SELECT SUM(CHECKING.balance) AS total_checking_balance
FROM ACCOUNTS
JOIN SAVINGS ON ACCOUNTS.custid = SAVINGS.custid;

SELECT attribute_id, attribute_name
FROM Attribute_Definitions
WHERE attribute_data_type = '0';

SELECT Customers.phone_number, Staff.phone_number
FROM Customers
JOIN Staff ON Customers.customer_id = Staff.staff_id;

SELECT name
FROM camera_lens
WHERE name LIKE '%Digital%';

SELECT Name
FROM actor
WHERE age != 20;

SELECT Things thing_id, Things.service_type_code, Organizations.organization_id
FROM Things
JOIN Organizations ON Things.organization_id = Organizations.organization_id;

SELECT AVG(wine.Price) AS AveragePrice
FROM wine
WHERE wine.State = 'Sonoma' AND wine.Appelation = 'Sonoma';

SELECT p.Player, p.Years_Played, p.Total_WL, p.Doubles_WL
FROM player p
WHERE p.Team = (SELECT Team_id FROM team WHERE Name = 'Columbus Crew');

SELECT Industry
FROM Companies
ORDER BY Industry DESC;

SELECT Age, COUNT(*) AS Number_of_students
FROM Student
GROUP BY Age;

SELECT publication.Publisher
FROM publication
WHERE publication.Price = (SELECT MAX(Price) FROM publication);

SELECT aircraft.aid
FROM aircraft
WHERE aircraft.distance > 1000;

SELECT airports.country, airports.altitude
FROM airports
WHERE airports.altitude IS MAX(airports.altitude);

SELECT Physician.Name
FROM Physician
WHERE Physician.Position LIKE '%senior%';

SELECT AVG(price_range) AS average_price
FROM Hotels
