SELECT pName, pID
FROM Player
WHERE decision = 'yes';

SELECT member.Name, college.Name
FROM member
JOIN college ON member.College_ID = college.College_ID;

SELECT crime_rate
FROM county_public_safety
ORDER BY Police_officers ASC;

SELECT Products.product_category_code, Products.product_description
FROM Products
WHERE product_name = 'chervil';

