SELECT Venue
FROM match
ORDER BY Date DESC;

SELECT name
FROM PersonFriend
WHERE city = 'New York';

SELECT p.Pilot_name
FROM pilot p
WHERE p.Team = 'Bradley' OR p.Team = 'Fordham';

SELECT p.Player_name, c.Club_name
FROM player p
JOIN coach c ON p.Player_ID = c.Coach_ID;

SELECT circuits.name
FROM circuits
WHERE circuits.country IN ('UK', 'Malaysia');

SELECT journalist.Name
FROM journalist
WHERE Nationality IN ('England', 'Wales');

SELECT document_name
FROM Documents
WHERE image_id IS NULL;

SELECT Location
FROM gas_station
ORDER BY Open_Year;

SELECT Name 
FROM climber
ORDER BY Points DESC;

SELECT AVG(Num_of_Shops) AS Average_Factories
FROM manufacturer
WHERE Num_of_Shops > 20;

SELECT Products.Name, Manufacturers.Code AS Manufacturer
FROM Products
JOIN Manufacturers ON Products.Code = Manufacturers.Code;

SELECT customer.cust_name, customer.acc_bal
FROM customer
WHERE customer.cust_name LIKE '%a%';

SELECT Name
FROM pilot
ORDER BY Name ASC;

SELECT stadium.name
FROM stadium
WHERE stadium.Capacity < (
    SELECT AVG(stadium.Capacity)
    FROM stadium
);

SELECT albums.title
FROM albums
WHERE albums.title LIKE 'A%';

SELECT employees.EMPLOYEE_ID, countries.COUNTRY_NAME
FROM employees
JOIN countries ON employees.COUNTRY_ID = countries.COUNTRY_ID;

SELECT problem_id
FROM Problems
WHERE reported_by_staff_id = (SELECT staff_id FROM Staff WHERE staff_first_name = 'Lysanne Turcotte' AND staff_last_name = 'Turcotte');

SELECT Name
FROM driver
WHERE Years_Working = (SELECT MAX(Years_Working) FROM school_bus);

SELECT race.Name, race.Date, track.Name
FROM race
JOIN track ON race.Track_ID = track.Track_ID;

SELECT Products.Product_Price
FROM Products
WHERE Product_Name = 'Dining' OR Product_Name = 'Trading Policy';

SELECT wine.Winery
FROM wine
WHERE wine.Score = (SELECT MAX(wine.Score) FROM wine);

SELECT Author, Scores
FROM submission
ORDER BY Scores ASC;

SELECT AllergyType, COUNT(*) AS Number_of_allergies
FROM Has_Allergy
GROUP BY AllergyType;

SELECT train_station.Location
FROM train_station
JOIN station ON train_station.Station_ID = station.Station_ID;

SELECT candidate.People_ID, candidate.Poll_Source, candidate.Date, candidate.Support_rate, candidate.Consider_rate, candidate.Oppose_rate, candidate.Unsure_rate
FROM candidate
JOIN people ON candidate.People_ID = people.People_ID;

SELECT AVG(room_count) AS average_room_count
FROM Apartments
WHERE apt_type_code = 'Studio';

SELECT employee.eid
FROM employee
WHERE employee.salary >= 100000;

SELECT COUNT(*) AS total_instructors
FROM instructor
WHERE semester = 'Spring' AND year = 2010;

SELECT Account_Details
FROM Accounts
WHERE Account_Details LIKE '%5%';

SELECT Patient.Name
FROM Appointment
JOIN Patient ON Appointment.Patient = Patient.SSN;

SELECT COUNT(*) AS STUDENTS_ENROLLED
FROM ENROLL
WHERE CLASS_CODE = 'ACCT-211';

SELECT CName
FROM Course
ORDER BY Credits;

SELECT Police_force
FROM county_public_safety
WHERE Location NOT IN ('East Side');

SELECT exhibition.Theme, exhibition.Year
FROM exhibition
ORDER BY exhibition.Ticket_Price DESC;

SELECT building.Name
FROM building
WHERE building.Height_feet >= 200 AND building.Floors >= 20;
